import { Textarea } from "@/components/ui/textarea"
import { Button } from "@/components/ui/button"
import { Label } from "@/components/ui/label"
import { SelectValue, SelectTrigger, SelectItem, SelectContent, Select } from "@/components/ui/select"
import Link from "next/link"
import { Download, PlayIcon } from "lucide-react"
import { useState } from "react"
import getAllVoices from "@/app/server/get-voices"
import { Voice, VoiceResponse } from "@/types"
import _, { set } from "lodash"
import { useCreateAudioBuffer } from "@/app/queries/useCreateAudioBuffer"
import CONSTANTS from "@/app/config/constants"
import { PlayButton } from "./ui/playButton"

type Props = {
  voices: Voice[]
  allVoices: VoiceResponse[]
}

export function VoicemailGreetingComponent({ voices, allVoices }: Props) {
  const [isPlaying, setIsPlaying] = useState(false)
  const [text, setText] = useState(
    "Thank you for calling. I apologize for missing your call. I'm busy right now, but if you leave your name, number, and message, I will return your call as soon as possible.",
  )
  const [audio, setAudio] = useState<HTMLAudioElement>()
  const [music, setMusic] = useState<string>("popular-corporate-upbeat")
  const [accent, setAccent] = useState<string>("american")
  const [selectedVoice, setVoice] = useState<string>("Rachel")
  const mutation = useCreateAudioBuffer(text, selectedVoice, music)

  const handlePlay = () => {
    if (isPlaying) {
      console.log(audio)
      audio?.pause()
      setIsPlaying(false)
      return
    }

    mutation.mutation.mutateAsync().then(async (d) => {
      const buffer = await d.blob()
      console.log(buffer)
      const url = URL.createObjectURL(buffer)
      const newAudio = new Audio(url)

      setAudio(newAudio)
      newAudio.onended = () => {
        setIsPlaying(false)
      }
      newAudio.onplay = () => {
        setIsPlaying(true)
      }

      newAudio.onloadedmetadata = () => {
        newAudio.play()
      }
    })
  }

  const download = () => {
    mutation.mutation.mutateAsync().then(async (d) => {
      const buffer = await d.blob()
      const url = URL.createObjectURL(buffer)
      const a = document.createElement("a")
      a.href = url
      a.download = "VoicemailGreeting.mp3"
      a.click()
    })
  }

  const filteredVoices = allVoices.filter((voice) => voice.labels.accent === accent)

  const onPlay = () => {
    const previewUrl = allVoices.find((voice) => voice.voice_id === selectedVoice)?.preview_url
    console.log(previewUrl)
    if (!previewUrl) return
    const audio = new Audio(previewUrl)
    audio.play()
    setAudio(audio)
  }

  return (
    <div className="max-w-2xl mx-auto p-4 bg-white rounded-lg shadow-md">
      <div className="mb-6">
        <Textarea className="w-full h-32 resize-none" onChange={(e) => setText(e.target.value)} value={text} />
        <div className="flex justify-end mt-4">
          <PlayButton isPlaying={isPlaying} isLoading={mutation.mutation.isPending} onClick={handlePlay} />
        </div>
      </div>
      <div className="grid grid-cols-2 gap-4 border-t border-b py-4">
        <div>
          <Label htmlFor="accent">Accent</Label>
          <Select value={accent} onValueChange={setAccent}>
            <SelectTrigger>
              <SelectValue placeholder="USA" />
            </SelectTrigger>
            <SelectContent>
              {Object.entries(voices).map(([accent, voices]) => (
                <SelectItem key={accent} value={accent}>
                  {/* Remove - and capitalize first letter */}
                  {accent.replace(/-/g, " ").replace(/\b\w/g, (char) => char.toUpperCase())}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
        <div>
          <Label htmlFor="voice">Voice</Label>
          <Select value={selectedVoice} onValueChange={setVoice}>
            <SelectTrigger>
              <SelectValue placeholder={filteredVoices.length > 0 ? filteredVoices[0].name : ""} />
            </SelectTrigger>
            <SelectContent>
              {allVoices
                .filter((voice) => voice?.labels?.accent === accent)
                .map((voice, i) => (
                  <SelectItem key={voice.voice_id} value={voice.name}>
                    {voice.name}
                  </SelectItem>
                ))}
            </SelectContent>
          </Select>
        </div>
      </div>
      <div className="grid grid-cols-2 gap-4 py-4">
        <div>
          <Label htmlFor="category">Category</Label>
          <Select>
            <SelectTrigger>
              <SelectValue placeholder="Corporate" />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="Corporate">Corporate</SelectItem>
              <SelectItem value="Narrative">Narrative</SelectItem>
              <SelectItem value="Commercial">Commercial</SelectItem>
            </SelectContent>
          </Select>
        </div>
        <div>
          <Label htmlFor="music">Music</Label>
          <Select value={music} onValueChange={setMusic}>
            <SelectTrigger>
              <SelectValue placeholder="Popular corporate upbeat" />
            </SelectTrigger>
            <SelectContent>
              {CONSTANTS.BG_MUSIC.map((music) => (
                <SelectItem key={music.text} value={music.file}>
                  {music.text}
                </SelectItem>
              ))}
            </SelectContent>
          </Select>
        </div>
      </div>
      <div className="flex items-center justify-between py-4">
        <PlayButton isPlaying={isPlaying} isLoading={mutation.mutation.isPending} onClick={handlePlay} />

        <div className="flex items-center">
          {/* Download button */}
          <Button variant="link" onClick={download}>
            <Download className="mr-2" />
            Download
          </Button>
        </div>
      </div>
      <Link className="text-sm text-gray-500 underline" href="#">
        Edit text
      </Link>
    </div>
  )
}

